package com.ofaro.participaciones;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import org.json.JSONArray;
import org.json.JSONObject;

import java.time.LocalDate;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ReservationsActivity extends Activity {
    private final ExecutorService io=Executors.newSingleThreadExecutor();private AppCore core;private LinearLayout page;private TextView subtitle;
    @Override protected void onCreate(Bundle b){super.onCreate(b);core=new AppCore(this);setContentView(build());showList("HOY");}
    @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
    private View build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(246,245,242));LinearLayout head=column();head.setPadding(dp(18),dp(15),dp(18),dp(13));head.setBackgroundColor(Color.rgb(15,15,15));head.addView(text("O FARO",23,Color.WHITE,true));subtitle=text("Reservas",13,Color.LTGRAY,false);head.addView(subtitle);root.addView(head);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=column();page.setPadding(dp(14),dp(14),dp(14),dp(30));scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));return root;}
    private void showList(String mode){clear("Reservas");back("Reservas",this::finish);LinearLayout filters=row();for(String m:new String[]{"HOY","PENDIENTES","ACTIVAS","HISTÓRICO"}){Button b=small(m);b.setEnabled(!m.equals(mode));b.setOnClickListener(v->showList(m));filters.addView(b,weight());}page.addView(filters);Button add=primary("+ NUEVA RESERVA");add.setOnClickListener(v->newReservation());page.addView(add,top(dp(10)));TextView status=text("Cargando…",14,Color.DKGRAY,false);status.setPadding(0,dp(12),0,dp(8));page.addView(status);LinearLayout list=column();page.addView(list);if(!requireApi())return;io.execute(()->{try{JSONObject req=core.action("reservationList").put("limit",250);if("HOY".equals(mode))req.put("date",LocalDate.now().toString());if("HISTÓRICO".equals(mode))req.put("includeClosed",true);JSONObject r=core.post(req);core.ensureOk(r);JSONArray raw=r.optJSONArray("items");if(raw==null)raw=new JSONArray();JSONArray out=new JSONArray();int people=0;for(int i=0;i<raw.length();i++){JSONObject x=raw.optJSONObject(i);if(x==null)continue;String state=x.optString("state","");if("PENDIENTES".equals(mode)&&!"Pendiente".equalsIgnoreCase(state))continue;if("ACTIVAS".equals(mode)&&("Cancelada".equalsIgnoreCase(state)||"Denegada".equalsIgnoreCase(state)))continue;out.put(x);people+=x.optInt("people",0);}JSONArray finalOut=out;int finalPeople=people;cache(finalOut);runOnUiThread(()->paintList(status,list,mode,finalOut,finalPeople,false));}catch(Exception e){JSONArray cached=cache();runOnUiThread(()->{if(cached.length()>0)paintList(status,list,mode,cached,0,true);else status.setText("Error: "+msg(e));});}});}
    private void paintList(TextView status,LinearLayout list,String mode,JSONArray arr,int people,boolean cached){status.setText((cached?"Sin conexión · copia guardada · ":"")+arr.length()+" reservas"+(people>0?" · "+people+" personas":""));list.removeAllViews();if(arr.length()==0){list.addView(text("No hay reservas en este filtro.",15,Color.DKGRAY,false));return;}for(int i=0;i<arr.length();i++){JSONObject r=arr.optJSONObject(i);if(r!=null)addCard(list,r);}}
    private void addCard(LinearLayout list,JSONObject r){LinearLayout c=card();c.addView(text(r.optString("date","")+" · "+r.optString("time","--:--"),13,Color.GRAY,true));c.addView(text(r.optString("name","Reserva"),20,Color.rgb(20,20,20),true));String meta=r.optInt("people",0)+" personas";if(!r.optString("table","").isEmpty())meta+=" · Mesa "+r.optString("table");if(!r.optString("zone","").isEmpty()&&!"Sin asignar".equalsIgnoreCase(r.optString("zone")))meta+=" · "+r.optString("zone");c.addView(text(meta,14,Color.DKGRAY,false));TextView st=text("Reserva: "+dash(r.optString("state","Pendiente"))+" · Servicio: "+dash(r.optString("serviceState","Pendiente")),13,Color.DKGRAY,false);st.setPadding(0,dp(5),0,dp(9));c.addView(st);LinearLayout row=row();Button print=small("TICKET");print.setOnClickListener(v->preview(r));Button manage=small("GESTIONAR");manage.setOnClickListener(v->details(r));row.addView(print,weight());row.addView(manage,weight());c.addView(row);list.addView(c,bottom(dp(9)));}
    private void details(JSONObject r){clear("Reserva");back("Reserva · "+r.optString("name",""),()->showList("HOY"));page.addView(info("Fecha / hora",r.optString("date","")+" · "+r.optString("time","")));page.addView(info("Personas",String.valueOf(r.optInt("people",0))));page.addView(info("Mesa / zona",dash(r.optString("table",""))+" · "+dash(r.optString("zone",""))));page.addView(info("Teléfono",dash(r.optString("phone",""))));page.addView(info("Correo",dash(r.optString("email",""))));page.addView(info("Observaciones",dash(r.optString("notes",""))));page.addView(info("Estado reserva",dash(r.optString("state","Pendiente"))));page.addView(info("Estado servicio",dash(r.optString("serviceState","Pendiente"))));Button preview=primary("PREVISUALIZAR / IMPRIMIR");preview.setOnClickListener(v->preview(r));page.addView(preview,top(dp(10)));Button edit=secondary("EDITAR DATOS, MESA Y ZONA");edit.setOnClickListener(v->edit(r));page.addView(edit,top(dp(8)));LinearLayout contact=row();Button call=small("LLAMAR");call.setOnClickListener(v->dial(r.optString("phone","")));Button wa=small("WHATSAPP");wa.setOnClickListener(v->whatsapp(r.optString("phone","")));contact.addView(call,weight());contact.addView(wa,weight());page.addView(contact,topWrap(dp(8)));page.addView(label("ESTADO DE RESERVA"));LinearLayout a=row();Button confirm=small("CONFIRMAR");confirm.setOnClickListener(v->decision(r,"Confirmada"));Button deny=small("DENEGAR");deny.setOnClickListener(v->decision(r,"Denegada"));a.addView(confirm,weight());a.addView(deny,weight());page.addView(a);LinearLayout b=row();Button pending=small("PENDIENTE");pending.setOnClickListener(v->action(r,"Pendiente","",false));Button cancel=small("CANCELAR");cancel.setOnClickListener(v->action(r,"Cancelada","",false));b.addView(pending,weight());b.addView(cancel,weight());page.addView(b,topWrap(dp(7)));page.addView(label("ESTADO DEL SERVICIO"));String[] ss={"Pendiente","Llegó","Sentada","En servicio","Completada","No se presentó"};for(int i=0;i<ss.length;i+=2){LinearLayout rr=row();for(int j=i;j<Math.min(i+2,ss.length);j++){String s=ss[j];Button x=small(s.toUpperCase());x.setOnClickListener(v->action(r,"",s,false));rr.addView(x,weight());}page.addView(rr,topWrap(dp(7)));}}
    private void decision(JSONObject r,String state){if(r.optString("email","").isEmpty()){action(r,state,"",false);return;}new AlertDialog.Builder(this).setTitle(state).setMessage("¿Enviar también el correo al cliente?").setNegativeButton("Cancelar",null).setNeutralButton("SIN CORREO",(d,w)->action(r,state,"",false)).setPositiveButton("ENVIAR CORREO",(d,w)->action(r,state,"",true)).show();}
    private void action(JSONObject r,String state,String service,boolean email){io.execute(()->{try{JSONObject q=core.action("reservationAction").put("id",r.optString("id","")).put("sendEmail",email).put("forceEmail",false);if(!state.isEmpty())q.put("state",state);if(!service.isEmpty())q.put("serviceState",service);JSONObject x=core.post(q);core.ensureOk(x);runOnUiThread(()->{toast("Reserva actualizada");showList("HOY");});}catch(Exception e){runOnUiThread(()->alert("No se pudo actualizar",msg(e)));}});}
    private void edit(JSONObject r){clear("Editar");back("Editar reserva",()->details(r));EditText date=field(page,"Fecha",r.optString("date",""),InputType.TYPE_CLASS_DATETIME);EditText time=field(page,"Hora",r.optString("time",""),InputType.TYPE_CLASS_DATETIME);EditText name=field(page,"Nombre",r.optString("name",""),InputType.TYPE_CLASS_TEXT);EditText phone=field(page,"Teléfono",r.optString("phone",""),InputType.TYPE_CLASS_PHONE);EditText email=field(page,"Correo",r.optString("email",""),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText people=field(page,"Personas",String.valueOf(r.optInt("people",2)),InputType.TYPE_CLASS_NUMBER);EditText table=field(page,"Mesa",r.optString("table",""),InputType.TYPE_CLASS_TEXT);EditText zone=field(page,"Zona",r.optString("zone","Sin asignar"),InputType.TYPE_CLASS_TEXT);EditText notes=multi(page,"Observaciones",r.optString("notes",""),4);Button save=primary("GUARDAR CAMBIOS");page.addView(save,top(dp(12)));save.setOnClickListener(v->{save.setEnabled(false);io.execute(()->{try{JSONObject q=core.action("reservationFullUpdate").put("id",r.optString("id","")).put("date",val(date)).put("time",val(time)).put("name",val(name)).put("phone",val(phone)).put("email",val(email)).put("people",parse(val(people),2)).put("table",val(table)).put("zone",val(zone)).put("notes",val(notes));JSONObject x=core.post(q);core.ensureOk(x);runOnUiThread(()->{toast("Reserva guardada");showList("HOY");});}catch(Exception e){runOnUiThread(()->{save.setEnabled(true);alert("Error",msg(e));});}});});}
    private void newReservation(){clear("Nueva reserva");back("Nueva reserva",()->showList("HOY"));EditText name=field(page,"Nombre","",InputType.TYPE_CLASS_TEXT);EditText phone=field(page,"Teléfono","",InputType.TYPE_CLASS_PHONE);EditText email=field(page,"Correo (opcional)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText date=field(page,"Fecha",LocalDate.now().toString(),InputType.TYPE_CLASS_DATETIME);EditText time=field(page,"Hora","14:00",InputType.TYPE_CLASS_DATETIME);EditText people=field(page,"Personas","2",InputType.TYPE_CLASS_NUMBER);EditText table=field(page,"Mesa (opcional)","",InputType.TYPE_CLASS_TEXT);EditText zone=field(page,"Zona","Sin asignar",InputType.TYPE_CLASS_TEXT);EditText notes=multi(page,"Observaciones","",4);Button save=primary("GUARDAR Y PREVISUALIZAR");page.addView(save,top(dp(12)));save.setOnClickListener(v->{if(val(name).isEmpty()||val(phone).isEmpty()){alert("Faltan datos","Nombre y teléfono son obligatorios.");return;}save.setEnabled(false);io.execute(()->{try{JSONObject q=core.action("reservationCreate").put("nombre",val(name)).put("telefono",val(phone)).put("correo",val(email)).put("fecha",val(date)).put("hora",val(time)).put("personas",Math.max(1,parse(val(people),2))).put("mesa",val(table)).put("zona",val(zone)).put("observaciones",val(notes));JSONObject x=core.post(q);core.ensureOk(x);JSONObject r=new JSONObject().put("id",x.optString("id","")).put("date",val(date)).put("time",val(time)).put("name",val(name)).put("phone",val(phone)).put("email",val(email)).put("people",parse(val(people),2)).put("table",val(table)).put("zone",val(zone)).put("notes",val(notes));runOnUiThread(()->{save.setEnabled(true);toast("Reserva guardada");preview(r);});}catch(Exception e){runOnUiThread(()->{save.setEnabled(true);alert("No se pudo guardar",msg(e));});}});});}
    private void preview(JSONObject r){StringBuilder b=new StringBuilder();b.append(r.optString("date","")).append("   ").append(r.optString("time","")).append("\n\n").append(r.optString("name","").toUpperCase()).append("\n").append(r.optInt("people",0)).append(" PERSONAS\n");if(!r.optString("table","").isEmpty())b.append("Mesa: ").append(r.optString("table")).append("\n");if(!r.optString("zone","").isEmpty()&&!"Sin asignar".equalsIgnoreCase(r.optString("zone")))b.append("Zona: ").append(r.optString("zone")).append("\n");if(!r.optString("phone","").isEmpty())b.append("Tel: ").append(r.optString("phone")).append("\n");if(!r.optString("notes","").isEmpty())b.append("\nOBSERVACIONES\n").append(r.optString("notes")).append("\n");b.append("\n").append(r.optString("id",""));Intent i=new Intent(this,TicketPreviewActivity.class);i.putExtra("title","MESÓN O FARO");i.putExtra("subtitle","RESERVA");i.putExtra("body",b.toString());i.putExtra("type","Reserva");i.putExtra("reference",r.optString("id",""));i.putExtra("detail",r.optString("name",""));i.putExtra("reservationId",r.optString("id",""));startActivity(i);}
    private void cache(JSONArray a){core.prefs().edit().putString("reservation_cache",a.toString()).apply();}private JSONArray cache(){try{return new JSONArray(core.prefs().getString("reservation_cache","[]"));}catch(Exception e){return new JSONArray();}}
    private void dial(String p){if(p==null||p.trim().isEmpty()){toast("No hay teléfono");return;}startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+p.trim())));}private void whatsapp(String p){if(p==null||p.trim().isEmpty()){toast("No hay teléfono");return;}String c=p.replaceAll("[^0-9]","");if(c.length()==9)c="34"+c;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+c)));}catch(Exception e){alert("WhatsApp",msg(e));}}
    private boolean requireApi(){if(core.configured())return true;alert("Falta configurar la API","Ve a Ajustes en Inicio.");return false;}private void clear(String s){page.removeAllViews();subtitle.setText(s);}private void back(String s,Runnable r){LinearLayout x=row();Button b=secondary("‹ ATRÁS");b.setOnClickListener(v->r.run());x.addView(b,new LinearLayout.LayoutParams(dp(105),dp(48)));TextView t=text(s,20,Color.rgb(20,20,20),true);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(10),0,0,0);x.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));page.addView(x);page.addView(space(dp(8)));}private TextView label(String s){TextView t=text(s,13,Color.DKGRAY,true);t.setPadding(0,dp(16),0,dp(7));return t;}private TextView info(String l,String v){TextView t=text(l.toUpperCase()+"\n"+v,14,Color.rgb(30,30,30),false);t.setPadding(dp(12),dp(10),dp(12),dp(10));t.setBackground(box(Color.WHITE,11,Color.rgb(218,218,218),1));t.setLayoutParams(bottom(dp(7)));return t;}private LinearLayout card(){LinearLayout c=column();c.setPadding(dp(14),dp(13),dp(14),dp(13));c.setBackground(box(Color.WHITE,14,Color.rgb(218,216,212),1));return c;}private LinearLayout column(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);return c;}private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);return r;}private Button primary(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setAllCaps(false);b.setBackground(box(Color.rgb(15,15,15),12,Color.TRANSPARENT,0));return b;}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.rgb(20,20,20));b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setAllCaps(false);b.setBackground(box(Color.WHITE,12,Color.rgb(190,190,190),1));return b;}private Button small(String s){Button b=secondary(s);b.setTextSize(10);return b;}private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private EditText input(String v){EditText e=new EditText(this);e.setText(v);e.setTextSize(16);e.setTextColor(Color.rgb(20,20,20));e.setPadding(dp(12),0,dp(12),0);e.setBackground(box(Color.WHITE,11,Color.rgb(205,205,205),1));return e;}private EditText field(LinearLayout p,String l,String v,int type){TextView t=text(l,13,Color.DKGRAY,true);t.setPadding(0,dp(8),0,dp(4));p.addView(t);EditText e=input(v);e.setInputType(type);e.setSingleLine(true);p.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(50)));return e;}private EditText multi(LinearLayout p,String l,String v,int lines){TextView t=text(l,13,Color.DKGRAY,true);t.setPadding(0,dp(8),0,dp(4));p.addView(t);EditText e=input(v);e.setSingleLine(false);e.setMinLines(lines);e.setGravity(Gravity.TOP);e.setPadding(dp(12),dp(9),dp(12),dp(9));p.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private GradientDrawable box(int f,int r,int s,int sw){GradientDrawable d=new GradientDrawable();d.setColor(f);d.setCornerRadius(dp(r));if(sw>0)d.setStroke(dp(sw),s);return d;}private LinearLayout.LayoutParams weight(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),0,dp(2),0);return p;}private LinearLayout.LayoutParams top(int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(52));p.topMargin=v;return p;}private LinearLayout.LayoutParams topWrap(int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.topMargin=v;return p;}private LinearLayout.LayoutParams bottom(int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.bottomMargin=v;return p;}private View space(int h){View v=new View(this);v.setLayoutParams(new LinearLayout.LayoutParams(1,h));return v;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private String val(EditText e){return e.getText().toString().trim();}private int parse(String s,int f){try{return Integer.parseInt(s.trim());}catch(Exception e){return f;}}private String dash(String s){return s==null||s.trim().isEmpty()?"—":s.trim();}private String msg(Throwable t){String m=t==null?"Error desconocido":t.getMessage();return m==null||m.trim().isEmpty()?String.valueOf(t):m;}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}private void alert(String t,String m){if(!isFinishing())new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("Aceptar",null).show();}
}
